(2982903, 418255, 21816, '<td valign="top">Great perspective. I love how glassy and reflective the water is!</td>', 'Great perspective. I love how glassy and reflective the water is!', '2006-11-01 09:32:04.000000', NULL, 1),
(2982913, 421068, 21816, '<td valign="top">Would of liked to have seen more detail in the groom...he''s a bit like a black shape! Everything else is excellent!</td>', 'Would of liked to have seen more detail in the groom...he''s a bit like a black shape! Everything else is excellent!', '2006-11-01 09:33:54.000000', NULL, 1),
(2982921, 420520, 21816, '<td valign="top">Great photo. She looks really proud!</td>', 'Great photo. She looks really proud!', '2006-11-01 09:35:07.000000', NULL, 1),
