(2982944, 420972, 48954, '<td valign="top">Vive le Quebec</td>', 'Vive le Quebec', '2006-11-01 09:38:45.000000', NULL, 1),
(2982965, 417866, 45559, '<td valign="top">It''s a good photo but is too dark. good luck</td>', 'It''s a good photo but is too dark. good luck', '2006-11-01 09:43:05.000000', NULL, 1),
(2982972, 420705, 13207, '<td valign="top">I love the expression on her face!</td>', 'I love the expression on her face!', '2006-11-01 09:44:21.000000', NULL, 1),
(2983005, 420818, 67258, '<td valign="top">The pose is just perfect, and I really like that the little girl is gazing out of the scene to the left of the photographer.  L:ighting is effective, and there is a good exposure throughout.  Good one!</td>', 'The pose is just perfect, and I really like that the little girl is gazing out of the scene to the left of the photographer.  L:ighting is effective, and there is a good exposure throughout.  Good one!', '2006-11-01 09:51:25.000000', NULL, 1),
(2983010, 420569, 48954, '<td valign="top">Irene?</td>', 'Irene?', '2006-11-01 09:51:59.000000', NULL, 1),
(2983013, 419394, 67258, '<td valign="top">A really good idea for a portrait, but it is a bit of a shame that the little one looks rather uncomfortable, and looking behind him as though to look for reassurance from someone just off shot.  Nonetheless, a nice scene.</td>', 'A really good idea for a portrait, but it is a bit of a shame that the little one looks rather uncomfortable, and looking behind him as though to look for reassurance from someone just off shot.  Nonetheless, a nice scene.', '2006-11-01 09:53:00.000000', NULL, 1),
(2983020, 417251, 67258, '<td valign="top">Love the use of ''negative'' space here.</td>', 'Love the use of ''negative'' space here.', '2006-11-01 09:54:12.000000', NULL, 1),
(2983025, 421056, 18095, '<td valign="top">Just takes your breath awayfabulous</td>', 'Just takes your breath awayfabulous', '2006-11-01 09:55:02.000000', NULL, 1),
(2983031, 420569, 33672, '<td valign="top">Wow! great tones,Texture, Bokeh and an interesting subject 10</td>', 'Wow! great tones,Texture, Bokeh and an interesting subject 10', '2006-11-01 09:55:49.000000', NULL, 1),
(2983033, 420985, 67258, '<td valign="top">Good exposure on the dark parts, but the burnt out highlights of the white part of dog''s coat do rather give the appearance of a disembodied head floating in space.  A hard one to balance well.</td>', 'Good exposure on the dark parts, but the burnt out highlights of the white part of dog''s coat do rather give the appearance of a disembodied head floating in space.  A hard one to balance well.', '2006-11-01 09:55:53.000000', NULL, 1),
(2983036, 420641, 67258, '<td valign="top">Expert exposure.</td>', 'Expert exposure.', '2006-11-01 09:56:24.000000', NULL, 1),
(2983052, 420715, 33672, '<td valign="top">Great comp and use of negative space...Face looks almost too smooth. A little less noise ninja or neat image would leave a bit more texture. (IMO)  Still a very strong photo. good luck with the shallenge.</td>', 'Great comp and use of negative space...Face looks almost too smooth. A little less noise ninja or neat image would leave a bit more texture. (IMO)  Still a very strong photo. good luck with the shallenge.', '2006-11-01 09:58:45.000000', NULL, 1),
(2983094, 420580, 117, '<td valign="top">Too much lighting underneath you could correct lat if you shot in raw.</td>', 'Too much lighting underneath you could correct lat if you shot in raw.', '2006-11-01 10:07:15.000000', NULL, 1),
(2983118, 420026, 117, '<td valign="top">Maybe a little soft but I do like those eyes.</td>', 'Maybe a little soft but I do like those eyes.', '2006-11-01 10:11:04.000000', NULL, 1),
(2983140, 420842, 52336, '<td valign="top">Whew.  Nice belt buckle. :) Great light, clarity is spot on, awesome portrait.</td>', 'Whew.  Nice belt buckle. :) Great light, clarity is spot on, awesome portrait.', '2006-11-01 10:13:48.000000', NULL, 1),
(2983150, 420573, 52336, '<td valign="top">:) Perfect lighting, nicely done.</td>', ':) Perfect lighting, nicely done.', '2006-11-01 10:15:09.000000', NULL, 1),
(2983151, 420804, 117, '<td valign="top">Not sure if the shirt is on backwards. I noticed that after the eyes and smile?</td>', 'Not sure if the shirt is on backwards. I noticed that after the eyes and smile?', '2006-11-01 10:15:15.000000', NULL, 1),
(2983156, 418054, 52336, '<td valign="top">Very cool.  Great use of the orientation, the backdrop is used well.  Nice job.</td>', 'Very cool.  Great use of the orientation, the backdrop is used well.  Nice job.', '2006-11-01 10:15:51.000000', NULL, 1),
(2983162, 420804, 52336, '<td valign="top">Very clever use of the orientation.  The tight focus and his "horizontal" position make it.  Great job.</td>', 'Very clever use of the orientation.  The tight focus and his "horizontal" position make it.  Great job.', '2006-11-01 10:16:35.000000', NULL, 1),
(2983170, 417882, 52336, '<td valign="top">Nicely set up, but lacks focus.  You''ve used the orientation well I think, and aside from being a bit underexposed in my view, the lighting is nice. 6</td>', 'Nicely set up, but lacks focus.  You''ve used the orientation well I think, and aside from being a bit underexposed in my view, the lighting is nice. 6', '2006-11-01 10:17:48.000000', NULL, 1),
(2983179, 421056, 52336, '<td valign="top">Wow.  What a beautiful portrait, and a beautiful girl.  Perfect light, crop/framing, expression, duotone, down to the slightly out of focus and beautiful chair back.  Deserves a 10.</td>', 'Wow.  What a beautiful portrait, and a beautiful girl.  Perfect light, crop/framing, expression, duotone, down to the slightly out of focus and beautiful chair back.  Deserves a 10.', '2006-11-01 10:19:19.000000', NULL, 1),
(2983187, 421072, 52336, '<td valign="top">These are the cutest trick or treaters. :) "Who are you and what am I doing here?" :D  A cute portrait, but had the background been more out of focus or darker, and the subject less centred, the impact would have been higher.</td>', 'These are the cutest trick or treaters. :) "Who are you and what am I doing here?" :D  A cute portrait, but had the background been more out of focus or darker, and the subject less centred, the impact would have been higher.', '2006-11-01 10:20:54.000000', NULL, 1),
(2983190, 420578, 52336, '<td valign="top">AWESOME use of the frame. :)  Very clever, and, I must say, a truly expressive portrait.  Nicely done!</td>', 'AWESOME use of the frame. :)  Very clever, and, I must say, a truly expressive portrait.  Nicely done!', '2006-11-01 10:21:31.000000', NULL, 1),
(2983257, 420441, 67705, '<td valign="top">Very nice subject (emotion, dress and hair style)<br/>good choice of background (color and texture)<br/>Gets my only 10.</td>', 'Very nice subject (emotion, dress and hair style)good choice of background (color and texture)Gets my only 10.', '2006-11-01 10:34:17.000000', NULL, 1),
