(2984504, 421056, 62318, '<td valign="top">Stunning photograph. Great lighting in the eyes. Great contrast. Nice lines with the arms. Great expression from the child. Picked to finish to 5.</td>', 'Stunning photograph. Great lighting in the eyes. Great contrast. Nice lines with the arms. Great expression from the child. Picked to finish to 5.', '2006-11-01 13:39:44.000000', NULL, 1),
