(2984511, 418255, 62318, '<td valign="top">The photo might be a little warm, especially in the skin tones. However I gave this a very high rating do to the excellent use of the entrire frame. The nice lines and gerat expsure.</td>', 'The photo might be a little warm, especially in the skin tones. However I gave this a very high rating do to the excellent use of the entrire frame. The nice lines and gerat expsure.', '2006-11-01 13:41:30.000000', NULL, 1),
(2984519, 420562, 62318, '<td valign="top">Wonderful photograph. Nice side lighting. Good light in the eyes. Myabe a few blown highlights. Nice use of the entire landscape frame /w good context. A very high rating in my book.</td>', 'Wonderful photograph. Nice side lighting. Good light in the eyes. Myabe a few blown highlights. Nice use of the entire landscape frame /w good context. A very high rating in my book.', '2006-11-01 13:43:00.000000', NULL, 1),
