(2984666, 420547, 58610, '<td valign="top">Hope nobody got hurt! Very playful and well composed.</td>', 'Hope nobody got hurt! Very playful and well composed.', '2006-11-01 14:18:47.000000', NULL, 1),
(2984678, 419508, 58610, '<td valign="top">Contrast is a little too much. Highlights are overpowering. Nice expression and composition.</td>', 'Contrast is a little too much. Highlights are overpowering. Nice expression and composition.', '2006-11-01 14:21:02.000000', NULL, 1),
