(2984692, 418335, 62095, '<td valign="top">I''m thinking that you entered this in the wrong one, but even then you would still get DNMC because it''s a landscape in landscape orientation.  <br/> <br/>Aside from that, I''d have probably given the photo itself a 6 in a free study or similar.</td>', 'I''m thinking that you entered this in the wrong one, but even then you would still get DNMC because it''s a landscape in landscape orientation.   Aside from that, I''d have probably given the photo itself a 6 in a free study or similar.', '2006-11-01 14:23:13.000000', NULL, 1),
(2984695, 420441, 62318, '<td valign="top">Beautiful color. Great lighting. Great Portrait. Great Model. It all adds up to a great picture. Eyes might be a little oversharpened for this resolution, that would be my only nitpick. Tied for 1st for me.</td>', 'Beautiful color. Great lighting. Great Portrait. Great Model. It all adds up to a great picture. Eyes might be a little oversharpened for this resolution, that would be my only nitpick. Tied for 1st for me.', '2006-11-01 14:23:36.000000', NULL, 1),
(2984696, 420705, 62318, '<td valign="top">Excellent use of the landscape frame. Great exposure. Even better expression. Nice color, lighting and depth. By far one of favorites and tied for a first place vote.</td>', 'Excellent use of the landscape frame. Great exposure. Even better expression. Nice color, lighting and depth. By far one of favorites and tied for a first place vote.', '2006-11-01 14:23:41.000000', NULL, 1),
(2984697, 420205, 58610, '<td valign="top">Very cute and playful. They were good sports.</td>', 'Very cute and playful. They were good sports.', '2006-11-01 14:23:44.000000', NULL, 1),
