(2987474, 420463, 18367, '<td valign="top">Best image I have seen so far.  Your choice of background, the blueish hue and the lady''s attire do indeed convey the message that it is a Cold Night.  That forlorn look in her eyes is in all probability that which captivated my interest the most.  Very well done.</td>', 'Best image I have seen so far.  Your choice of background, the blueish hue and the lady''s attire do indeed convey the message that it is a Cold Night.  That forlorn look in her eyes is in all probability that which captivated my interest the most.  Very well done.', '2006-11-02 00:05:46.000000', NULL, 1),
(2987481, 419864, 66515, '<td valign="top">Not really a portrait. Needs to decide who/what is the subject and focus on that.</td>', 'Not really a portrait. Needs to decide who/what is the subject and focus on that.', '2006-11-02 00:09:02.000000', NULL, 1),
