(2993175, 419817, 39349, '<td valign="top">Returning for comments.<br/> <br/>Very high-key, and I like it! I feel like busting out some old Duran Duran or Siouxsie and the Banshees albums right now. Great framing of the subject and you''ve really pulled off the high-key shot without over doing it IMHO.</td>', 'Returning for comments. Very high-key, and I like it! I feel like busting out some old Duran Duran or Siouxsie and the Banshees albums right now. Great framing of the subject and you''ve really pulled off the high-key shot without over doing it IMHO.', '2006-11-03 09:24:43.000000', NULL, 1),
(2993180, 418032, 49109, '<td valign="top">wish there was some more light on yourself. otherwise well done</td>', 'wish there was some more light on yourself. otherwise well done', '2006-11-03 09:25:47.000000', NULL, 1),
