(2994222, 421111, 3569, '<td valign="top">Well I will be joining you at the bottom of the pack.  I think the bottom is mine.  VAn</td>', 'Well I will be joining you at the bottom of the pack.  I think the bottom is mine.  VAn', '2006-11-03 14:14:23.000000', NULL, 1),
