(2994501, 417474, 60320, '<td valign="top">I had to look at this photo for a while before I could decide if I liked the rotation or not.  I think it works really well having her face exactly upright in the image, playing tricks with my eyes.  They yellow line leads nicely into the picture as well.  Cool idea. I like it!</td>', 'I had to look at this photo for a while before I could decide if I liked the rotation or not.  I think it works really well having her face exactly upright in the image, playing tricks with my eyes.  They yellow line leads nicely into the picture as well.  Cool idea. I like it!', '2006-11-03 15:31:46.000000', NULL, 1),
(2994507, 420578, 22734, '<td valign="top">Lol. This would swept to the top on an abstract challenge. Very well captured. 7</td>', 'Lol. This would swept to the top on an abstract challenge. Very well captured. 7', '2006-11-03 15:33:19.000000', NULL, 1),
(2994514, 420957, 22734, '<td valign="top">Great dramatic capture that spills out of the frame. 7</td>', 'Great dramatic capture that spills out of the frame. 7', '2006-11-03 15:35:02.000000', NULL, 1),
