INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2995661, 420452, 62187, '<td valign="top">Great colors and focus.</td>', 'Great colors and focus.', '2006-11-03 19:58:05.000000', NULL, 1),
(2995662, 420040, 62187, '<td valign="top">I wonder what the other side is like? Nice photo...looks like a poster or album cover.</td>', 'I wonder what the other side is like? Nice photo...looks like a poster or album cover.', '2006-11-03 19:58:50.000000', NULL, 1),
(2995666, 420216, 62187, '<td valign="top">She looks like she has a happy soul...nice photo.</td>', 'She looks like she has a happy soul...nice photo.', '2006-11-03 19:59:14.000000', NULL, 1),
(2995667, 420004, 62187, '<td valign="top">It''s a hyena right? Jackal? Oh well...it''s a super nice photo.</td>', 'It''s a hyena right? Jackal? Oh well...it''s a super nice photo.', '2006-11-03 19:59:47.000000', NULL, 1),
(2995671, 421046, 62187, '<td valign="top">Very nice...I hope you print it out, frame it and give her a copy to save for when she''s older. Nice job!</td>', 'Very nice...I hope you print it out, frame it and give her a copy to save for when she''s older. Nice job!', '2006-11-03 20:01:03.000000', NULL, 1),
(2995672, 419896, 62187, '<td valign="top">Very cute!</td>', 'Very cute!', '2006-11-03 20:01:12.000000', NULL, 1),
(2995673, 420193, 62187, '<td valign="top">Why the black and white? He looks like a colorful character.</td>', 'Why the black and white? He looks like a colorful character.', '2006-11-03 20:01:46.000000', NULL, 1),
(2995676, 419285, 62187, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2006-11-03 20:02:05.000000', NULL, 1),
(2995678, 421076, 62187, '<td valign="top">Nice lighting and that look on her face...I''m bumping up to an 8.</td>', 'Nice lighting and that look on her face...I''m bumping up to an 8.', '2006-11-03 20:03:02.000000', NULL, 1),
(2995681, 421105, 62187, '<td valign="top">I totally love this photo...why so small?</td>', 'I totally love this photo...why so small?', '2006-11-03 20:03:24.000000', NULL, 1),
(2995686, 420446, 62187, '<td valign="top">To me, it almost looks like the eye was oversharpened. Maybe not..? 7</td>', 'To me, it almost looks like the eye was oversharpened. Maybe not..? 7', '2006-11-03 20:04:27.000000', NULL, 1),
(2995689, 419892, 62187, '<td valign="top">Now it''s time to get outside and get some fresh air! Hope your''re feeling better Lily! Don''t look at my photo or you might get sick again - according to the voters. Good luck to ya!</td>', 'Now it''s time to get outside and get some fresh air! Hope your''re feeling better Lily! Don''t look at my photo or you might get sick again - according to the voters. Good luck to ya!', '2006-11-03 20:06:13.000000', NULL, 1),
(2995695, 418604, 62187, '<td valign="top">Can we say ''Cosmopolitan Magazine''? Nice photo.</td>', 'Can we say ''Cosmopolitan Magazine''? Nice photo.', '2006-11-03 20:06:55.000000', NULL, 1),
(2995697, 420415, 62187, '<td valign="top">The photo is dark but I like it.</td>', 'The photo is dark but I like it.', '2006-11-03 20:07:16.000000', NULL, 1),
(2995700, 419941, 62187, '<td valign="top">Why B&amp;W? It''s so nice and cats usually have great colors...oh well. Good luck to ya!</td>', 'Why B&W? It''s so nice and cats usually have great colors...oh well. Good luck to ya!', '2006-11-03 20:08:17.000000', NULL, 1),
(2995705, 420715, 62187, '<td valign="top">To me, it looks like an example of soft focus that I can''t master. Anyway, I like the photo...the pastel colors against the black background are nice.</td>', 'To me, it looks like an example of soft focus that I can''t master. Anyway, I like the photo...the pastel colors against the black background are nice.', '2006-11-03 20:09:32.000000', NULL, 1),
(2995706, 420641, 62187, '<td valign="top">I like it and think it meets the challenge perfectly...much more then most of the photos I''ve looked at so far. I think you''ll do well.</td>', 'I like it and think it meets the challenge perfectly...much more then most of the photos I''ve looked at so far. I think you''ll do well.', '2006-11-03 20:09:42.000000', NULL, 1),
(2995707, 420932, 62187, '<td valign="top">Just don''t scratch my eyes out like that other girl in the challenge. Great focus!</td>', 'Just don''t scratch my eyes out like that other girl in the challenge. Great focus!', '2006-11-03 20:10:21.000000', NULL, 1),
(2995710, 418779, 62187, '<td valign="top">Now that''s a portrait!</td>', 'Now that''s a portrait!', '2006-11-03 20:10:25.000000', NULL, 1),
(2995714, 420026, 62187, '<td valign="top">Are you in for a surprise...wait ''till they grow up! Great photo!</td>', 'Are you in for a surprise...wait ''till they grow up! Great photo!', '2006-11-03 20:11:02.000000', NULL, 1),
(2995717, 418056, 62187, '<td valign="top">Why are you alone? There''s like a million people behind you. Really colorful.</td>', 'Why are you alone? There''s like a million people behind you. Really colorful.', '2006-11-03 20:11:51.000000', NULL, 1),
(2995721, 420675, 62187, '<td valign="top">They look nothing alike! Just kidding...nice portrait.</td>', 'They look nothing alike! Just kidding...nice portrait.', '2006-11-03 20:12:23.000000', NULL, 1),
(2995723, 419508, 62187, '<td valign="top">The dull (not in a bad way) colors are working very well together. Nice photo.</td>', 'The dull (not in a bad way) colors are working very well together. Nice photo.', '2006-11-03 20:13:00.000000', NULL, 1),
(2995725, 420592, 62187, '<td valign="top">I hope other voters aren''t distracted by that stick. I think it makes the photo. Nice work.</td>', 'I hope other voters aren''t distracted by that stick. I think it makes the photo. Nice work.', '2006-11-03 20:13:48.000000', NULL, 1),
(2995730, 421126, 62187, '<td valign="top">I''ve seen her before in here I''m pretty sure. Just a tad dark? Certainly expressive though!</td>', 'I''ve seen her before in here I''m pretty sure. Just a tad dark? Certainly expressive though!', '2006-11-03 20:14:58.000000', NULL, 1),
(2995732, 420718, 62187, '<td valign="top">So many options with advanced editing. I would have cloned the white spot on his right shoulder out. It''s probably a reflection off the zipper (?). I''m not sure what the title has to do with the photo - I would think it''s a kind of color that could have been incorperated into the photo. The crop is nice.</td>', 'So many options with advanced editing. I would have cloned the white spot on his right shoulder out. It''s probably a reflection off the zipper (?). I''m not sure what the title has to do with the photo - I would think it''s a kind of color that could have been incorperated into the photo. The crop is nice.', '2006-11-03 20:15:02.000000', NULL, 1),
(2995746, 421151, 62187, '<td valign="top">If that''s a dude in there you should be ashamed of yourself. What are you thinking! That''s just strange man. Just kidding! I remember seeing this costume from when I was a kid...some kind of books? Anyway...nice photo! (If it''s a girl in the costume...well...ok...sorry for my ignorance or lack of memory - it''s still a nice photo!)</td>', 'If that''s a dude in there you should be ashamed of yourself. What are you thinking! That''s just strange man. Just kidding! I remember seeing this costume from when I was a kid...some kind of books? Anyway...nice photo! (If it''s a girl in the costume...well...ok...sorry for my ignorance or lack of memory - it''s still a nice photo!)', '2006-11-03 20:17:59.000000', NULL, 1),
(2995748, 420035, 62187, '<td valign="top">Well, it''s not the most interesting photo but...it is a well done photo and I feel it is also very expressive...well done.</td>', 'Well, it''s not the most interesting photo but...it is a well done photo and I feel it is also very expressive...well done.', '2006-11-03 20:18:10.000000', NULL, 1),
(2995751, 420711, 62187, '<td valign="top">Reminds me of a movie poster...wondering about the tilt of the background.</td>', 'Reminds me of a movie poster...wondering about the tilt of the background.', '2006-11-03 20:19:02.000000', NULL, 1),
(2995753, 418598, 62187, '<td valign="top">She''s not giving me the ''L on the forehead'' sign is she? Just kidding...nice pastel colors.</td>', 'She''s not giving me the ''L on the forehead'' sign is she? Just kidding...nice pastel colors.', '2006-11-03 20:19:53.000000', NULL, 1),
(2995755, 418950, 62187, '<td valign="top">He might need another coat then! Great focus!</td>', 'He might need another coat then! Great focus!', '2006-11-03 20:20:21.000000', NULL, 1),
(2995765, 420845, 62187, '<td valign="top">Hark, what yonder window breaks? Tis the sun and Juliet is the east...something like that. Yes, I used a magnifying glass so I could see what the book was. Nice photo!</td>', 'Hark, what yonder window breaks? Tis the sun and Juliet is the east...something like that. Yes, I used a magnifying glass so I could see what the book was. Nice photo!', '2006-11-03 20:23:23.000000', NULL, 1),
(2995775, 417682, 62187, '<td valign="top">It looks at least that she''s first in line. Super nice colors and focus.</td>', 'It looks at least that she''s first in line. Super nice colors and focus.', '2006-11-03 20:25:33.000000', NULL, 1),
(2995778, 418255, 62187, '<td valign="top">I''m not sure what a ''Guido'' is but I do know that''s a killer reflection in the water.</td>', 'I''m not sure what a ''Guido'' is but I do know that''s a killer reflection in the water.', '2006-11-03 20:26:30.000000', NULL, 1),
(2995783, 420558, 62187, '<td valign="top">It''s a little dark but I like it. Oh, I get it...like Dawn...in the early morning light...or...is her name Dawn? Regardless..nice photo!</td>', 'It''s a little dark but I like it. Oh, I get it...like Dawn...in the early morning light...or...is her name Dawn? Regardless..nice photo!', '2006-11-03 20:28:11.000000', NULL, 1),
(2995785, 420877, 62187, '<td valign="top">Wow...your edit reminds me of an old-timey photo...like in the 60''s or something. Hey, I was born in the 60''s...does that make me old-timey?</td>', 'Wow...your edit reminds me of an old-timey photo...like in the 60''s or something. Hey, I was born in the 60''s...does that make me old-timey?', '2006-11-03 20:29:21.000000', NULL, 1),
(2995787, 417532, 62187, '<td valign="top">What? And no camera yet? Sheesh...<br/>Welcome to the World Lily Mae!</td>', 'What? And no camera yet? Sheesh...Welcome to the World Lily Mae!', '2006-11-03 20:30:15.000000', NULL, 1),
(2995793, 418690, 62187, '<td valign="top">''Hey, thought you were photographing the sunrise? Well, I was. You''re somebody''s son and you did grow up. That''s like ''rising''...see?<br/> <br/>Don''t worry...I got ya covered. Nice photo!</td>', '''Hey, thought you were photographing the sunrise? Well, I was. You''re somebody''s son and you did grow up. That''s like ''rising''...see? Don''t worry...I got ya covered. Nice photo!', '2006-11-03 20:32:49.000000', NULL, 1),
(2995794, 420522, 62187, '<td valign="top">I can only imagine what''s in-store for us. Nice capture.</td>', 'I can only imagine what''s in-store for us. Nice capture.', '2006-11-03 20:33:36.000000', NULL, 1),
(2995798, 420603, 64928, '<td valign="top">Sorry, but the face seems overly highlighted to me.</td>', 'Sorry, but the face seems overly highlighted to me.', '2006-11-03 20:34:17.000000', NULL, 1),
(2995801, 420611, 62187, '<td valign="top">Was this an outake from the ''Wind'' challenge? No wind huh? Anyway...great colors in the photo.</td>', 'Was this an outake from the ''Wind'' challenge? No wind huh? Anyway...great colors in the photo.', '2006-11-03 20:34:46.000000', NULL, 1),
(2995803, 419953, 65324, '<td valign="top">Good picture.  Emotional.  Tells a story.  Wish the face had a little more light on it.  -6-</td>', 'Good picture.  Emotional.  Tells a story.  Wish the face had a little more light on it.  -6-', '2006-11-03 20:35:47.000000', NULL, 1),
(2995810, 419049, 62187, '<td valign="top">And you just stay there young missy! You''re never going outside...people out there are such creeps. Teasing...great photo...you got the mood perfectly for the title.</td>', 'And you just stay there young missy! You''re never going outside...people out there are such creeps. Teasing...great photo...you got the mood perfectly for the title.', '2006-11-03 20:36:31.000000', NULL, 1),
(2995811, 421135, 64928, '<td valign="top">Sorry, the glare on the glasses is distracting</td>', 'Sorry, the glare on the glasses is distracting', '2006-11-03 20:36:55.000000', NULL, 1),
(2995812, 418909, 62187, '<td valign="top">I Wa''na Go Too!! Well...why are you just sitting there? Super nice focus.</td>', 'I Wa''na Go Too!! Well...why are you just sitting there? Super nice focus.', '2006-11-03 20:37:05.000000', NULL, 1),
(2995816, 421109, 62187, '<td valign="top">Why ?...Because the sky is blue. Come on now...cheer up...it can''t be that bad! Nice use of low lighting.</td>', 'Why ?...Because the sky is blue. Come on now...cheer up...it can''t be that bad! Nice use of low lighting.', '2006-11-03 20:37:54.000000', NULL, 1),
(2995821, 421077, 65324, '<td valign="top">Good picture, little soft. -5-</td>', 'Good picture, little soft. -5-', '2006-11-03 20:39:35.000000', NULL, 1),
(2995822, 420957, 62187, '<td valign="top">Google for ''Irie'' - Jamaica, Radio Station, Bob Marley - thanks for the lesson and the great photo!</td>', 'Google for ''Irie'' - Jamaica, Radio Station, Bob Marley - thanks for the lesson and the great photo!', '2006-11-03 20:39:38.000000', NULL, 1),
(2995824, 420822, 62187, '<td valign="top">Great soft focus and crop/frame. Thin white border might make it look even nicer I think???? Nice photo regardless.</td>', 'Great soft focus and crop/frame. Thin white border might make it look even nicer I think???? Nice photo regardless.', '2006-11-03 20:40:37.000000', NULL, 1),
(2995830, 418912, 64928, '<td valign="top">Ver pretty model.  I think it would have been even better with the lighting from just a little different anglet to lessen the shadows on her face and neck. JMO)</td>', 'Ver pretty model.  I think it would have been even better with the lighting from just a little different anglet to lessen the shadows on her face and neck. JMO)', '2006-11-03 20:42:09.000000', NULL, 1),
(2995833, 420470, 62187, '<td valign="top">...and hopefully he won''t turn into a frog! Tell your parents they did a good job with their photo of you. Maybe they could make is just slightly brighter next time. Just a thought.</td>', '...and hopefully he won''t turn into a frog! Tell your parents they did a good job with their photo of you. Maybe they could make is just slightly brighter next time. Just a thought.', '2006-11-03 20:43:06.000000', NULL, 1),
(2995835, 420569, 64928, '<td valign="top">Haunting eye, good detail in the face.</td>', 'Haunting eye, good detail in the face.', '2006-11-03 20:43:56.000000', NULL, 1),
(2995837, 418514, 62187, '<td valign="top">Don''t see this kind of border too much. Why the crop? Look and listen before you speak? If so, nice touch.</td>', 'Don''t see this kind of border too much. Why the crop? Look and listen before you speak? If so, nice touch.', '2006-11-03 20:44:04.000000', NULL, 1),
(2995842, 419369, 62187, '<td valign="top">Wow...she looks really, really worried. Ok, you got your great photo, now put your camera down and give her some comfort! };&gt;)</td>', 'Wow...she looks really, really worried. Ok, you got your great photo, now put your camera down and give her some comfort! };>)', '2006-11-03 20:45:16.000000', NULL, 1),
(2995850, 421098, 62187, '<td valign="top">You got that right! I hope you''ve got a shotgun or at least plan to get one in about 12 years. Lock the back-door too. Great photo!</td>', 'You got that right! I hope you''ve got a shotgun or at least plan to get one in about 12 years. Lock the back-door too. Great photo!', '2006-11-03 20:46:44.000000', NULL, 1),
