(3005233, 420711, 64670, '<td valign="top">Fantastic</td>', 'Fantastic', '2006-11-06 07:50:39.000000', NULL, 1),
(3005236, 419541, 64670, '<td valign="top">I can''t say this is much of a portrait - the person is almost insignifigant.  More a landscape to me - having said that, beautiful reflection!</td>', 'I can''t say this is much of a portrait - the person is almost insignifigant.  More a landscape to me - having said that, beautiful reflection!', '2006-11-06 07:52:40.000000', NULL, 1),
(3005240, 419338, 51653, '<td valign="top">Great colors, but it is not a portrait. DNMC</td>', 'Great colors, but it is not a portrait. DNMC', '2006-11-06 07:57:02.000000', NULL, 1),
(3005241, 418248, 64670, '<td valign="top">The crop is a bit tight, seems like he''s in a box.  The brightness in the front right hand corner is a bit distracting.</td>', 'The crop is a bit tight, seems like he''s in a box.  The brightness in the front right hand corner is a bit distracting.', '2006-11-06 07:57:27.000000', NULL, 1),
(3005248, 418635, 51653, '<td valign="top">I like this shot (especially the colors), but I find the crop a bit too tight: I would like a bit more space above the hairs.</td>', 'I like this shot (especially the colors), but I find the crop a bit too tight: I would like a bit more space above the hairs.', '2006-11-06 08:00:10.000000', NULL, 1),
(3005259, 421111, 51653, '<td valign="top">DNMC</td>', 'DNMC', '2006-11-06 08:06:40.000000', NULL, 1),
(3005331, 419941, 51653, '<td valign="top">It could be a good cat portrait, but the out of focus nose is not very pleasant (IMO). A good shot otherwise.</td>', 'It could be a good cat portrait, but the out of focus nose is not very pleasant (IMO). A good shot otherwise.', '2006-11-06 08:42:42.000000', NULL, 1),
(3005398, 419824, 30049, '<td valign="top">It''s Belushi!  :D  Wild looking outfit this guy is wearing.  Fun to look at.  Seems more candid than portrait IMO.  The lighting looked to be quite challenging to work with in this photo.  The highlights are blown out in the harsh sunlight.  Surprised to see what looks like motion blur on his arm/sleeve area (or is it slightly OOF with a very shallow DOF?).  Very cool bokeh working in the background.  :)  Good luck in the challenge.</td>', 'It''s Belushi!  :D  Wild looking outfit this guy is wearing.  Fun to look at.  Seems more candid than portrait IMO.  The lighting looked to be quite challenging to work with in this photo.  The highlights are blown out in the harsh sunlight.  Surprised to see what looks like motion blur on his arm/sleeve area (or is it slightly OOF with a very shallow DOF?).  Very cool bokeh working in the background.  :)  Good luck in the challenge.', '2006-11-06 09:07:59.000000', NULL, 1),
(3005402, 418790, 30049, '<td valign="top">Cute.  Congratulations are in order on a new member of the family?  As for the photo itself, couple of things holding it back IMO.  It''s a little flat and the tonal range is short (needs more contrast, and the levels could be adjusted for a truer black and white).  The focus isn''t as sharp as it should be, especially around the face and eyes.  Best of luck to you in the challenge.</td>', 'Cute.  Congratulations are in order on a new member of the family?  As for the photo itself, couple of things holding it back IMO.  It''s a little flat and the tonal range is short (needs more contrast, and the levels could be adjusted for a truer black and white).  The focus isn''t as sharp as it should be, especially around the face and eyes.  Best of luck to you in the challenge.', '2006-11-06 09:10:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3005419, 421068, 30049, '<td valign="top">This is certainly a fun photo to look at.  Not really sure how it fits as a portrait.  Seems more like a candid or snapshot kind of image IMO.  Subject is a bit distant and small for a true portrait and this allows the surrounding areas to be a distraction in this busy scene.  All JMO of course.  Good luck in the challenge.</td>', 'This is certainly a fun photo to look at.  Not really sure how it fits as a portrait.  Seems more like a candid or snapshot kind of image IMO.  Subject is a bit distant and small for a true portrait and this allows the surrounding areas to be a distraction in this busy scene.  All JMO of course.  Good luck in the challenge.', '2006-11-06 09:13:46.000000', NULL, 1),
(3005447, 418576, 30049, '<td valign="top">This is a happy looking fellow.  :D  Nice photograph overall.  Good detail in his face (although his jacket seems sharper for some reason).  Minor observation/complaint is I think the image would have a little more impact if he was moved a little to the left to get more off-center.  Anyway, well done.  Good luck in the challenge.</td>', 'This is a happy looking fellow.  :D  Nice photograph overall.  Good detail in his face (although his jacket seems sharper for some reason).  Minor observation/complaint is I think the image would have a little more impact if he was moved a little to the left to get more off-center.  Anyway, well done.  Good luck in the challenge.', '2006-11-06 09:23:51.000000', NULL, 1),
(3005487, 418685, 45115, '<td valign="top">the best of this challenge... fantastic</td>', 'the best of this challenge... fantastic', '2006-11-06 09:40:23.000000', NULL, 1),
(3005490, 420842, 45115, '<td valign="top">yeah... you are the hardest horse of the challenge dude!</td>', 'yeah... you are the hardest horse of the challenge dude!', '2006-11-06 09:41:21.000000', NULL, 1),
(3005497, 420148, 45115, '<td valign="top">very interesting</td>', 'very interesting', '2006-11-06 09:44:22.000000', NULL, 1),
(3005504, 420845, 45115, '<td valign="top">thats a sexy babe for sure</td>', 'thats a sexy babe for sure', '2006-11-06 09:47:06.000000', NULL, 1),
(3005516, 421105, 51653, '<td valign="top">The shot is too little to be really evaluated. It seems a good one and I like the impression, but why did you post it so little?</td>', 'The shot is too little to be really evaluated. It seems a good one and I like the impression, but why did you post it so little?', '2006-11-06 09:52:55.000000', NULL, 1),
(3005564, 420914, 51653, '<td valign="top">It was really a bad day! <br/>Even if this shot captures the watcher attention there a re a couple of things that damage the overall effect (IMO). First of all, the rip on the cyan cloth is not very pleasant and it gives more the sensation of a photo collage than the sensation of the face coming out from the cloth. Furthermore, Im finding quite hard considering it as a portrait</td>', 'It was really a bad day! Even if this shot captures the watcher attention there a re a couple of things that damage the overall effect (IMO). First of all, the rip on the cyan cloth is not very pleasant and it gives more the sensation of a photo collage than the sensation of the face coming out from the cloth. Furthermore, Im finding quite hard considering it as a portrait', '2006-11-06 10:20:15.000000', NULL, 1),
(3005567, 419104, 65083, '<td valign="top">Great picture. You made it look like you could go up and pet him.</td>', 'Great picture. You made it look like you could go up and pet him.', '2006-11-06 10:22:43.000000', NULL, 1),
(3005568, 418442, 51653, '<td valign="top">I think a tighter crop to eliminate the out of focus white part on the first plan should work better.</td>', 'I think a tighter crop to eliminate the out of focus white part on the first plan should work better.', '2006-11-06 10:23:23.000000', NULL, 1),
(3005574, 419270, 51653, '<td valign="top">IMO the out of focus red part covering the face is not very pleasant, and really damages a shot with very interesting colors.</td>', 'IMO the out of focus red part covering the face is not very pleasant, and really damages a shot with very interesting colors.', '2006-11-06 10:24:56.000000', NULL, 1),
(3005576, 419541, 51653, '<td valign="top">Beautiful colors and relaxing image, but it DNMC</td>', 'Beautiful colors and relaxing image, but it DNMC', '2006-11-06 10:25:00.000000', NULL, 1),
(3005577, 421143, 51653, '<td valign="top">What an amazing sea scape. I love it, but it DNMC.</td>', 'What an amazing sea scape. I love it, but it DNMC.', '2006-11-06 10:25:06.000000', NULL, 1),
(3005579, 419291, 65083, '<td valign="top">Great picture, wish my cat''s would hold that still.</td>', 'Great picture, wish my cat''s would hold that still.', '2006-11-06 10:25:19.000000', NULL, 1),
(3005584, 418617, 65083, '<td valign="top">I like the look in his eyes, you want me to do what again!</td>', 'I like the look in his eyes, you want me to do what again!', '2006-11-06 10:28:00.000000', NULL, 1),
(3005587, 420012, 51653, '<td valign="top">I do not really like the green lines you used for the breath (was it a penlight?), maybe blurring them a bit would improve the effect.</td>', 'I do not really like the green lines you used for the breath (was it a penlight?), maybe blurring them a bit would improve the effect.', '2006-11-06 10:28:30.000000', NULL, 1),
(3005592, 419473, 33400, '<td valign="top">Very nice action.  Perhaps a bit over-sharpened though.</td>', 'Very nice action.  Perhaps a bit over-sharpened though.', '2006-11-06 10:29:48.000000', NULL, 1),
(3005601, 418366, 51653, '<td valign="top">I would prefer having both eyes well focused</td>', 'I would prefer having both eyes well focused', '2006-11-06 10:32:23.000000', NULL, 1),
(3005611, 420993, 51653, '<td valign="top">I do not really like the light you used: in my opinion it is somewhat flat, simultaneously burning parts of the head and leaving the collar too dark.</td>', 'I do not really like the light you used: in my opinion it is somewhat flat, simultaneously burning parts of the head and leaving the collar too dark.', '2006-11-06 10:34:46.000000', NULL, 1),
(3005618, 419987, 51653, '<td valign="top">A delicate shot, but I find the effect damaged by the too high contrast</td>', 'A delicate shot, but I find the effect damaged by the too high contrast', '2006-11-06 10:36:26.000000', NULL, 1),
(3005621, 417552, 51653, '<td valign="top">Well focused and composed, but the partial desaturation is not to my taste</td>', 'Well focused and composed, but the partial desaturation is not to my taste', '2006-11-06 10:37:19.000000', NULL, 1),
(3005624, 419266, 51653, '<td valign="top">I do not love partial desaturated images. In this case I find it really damaging an otherwise nice shot</td>', 'I do not love partial desaturated images. In this case I find it really damaging an otherwise nice shot', '2006-11-06 10:38:10.000000', NULL, 1),
(3005656, 418796, 51653, '<td valign="top">I generally do not love partial desaturation. For some reason I do not find it unpleasant here, but I do not really enjoy this (interesting) shot as a portrait mainly due to the lack of details on the main subject face.</td>', 'I generally do not love partial desaturation. For some reason I do not find it unpleasant here, but I do not really enjoy this (interesting) shot as a portrait mainly due to the lack of details on the main subject face.', '2006-11-06 10:45:55.000000', NULL, 1),
(3005828, 419338, 208, '<td valign="top">I''ll let everyone else tell you DNMC; here''s what I like about the picture. I like the sets of lines and how each is different: foreground bushes, red tree line, hazy horizon, even those top clouds. The colors aren''t oversaturated the way so many are over in the Free Study challenge. Nicely composed, well-thought out shot.</td>', 'I''ll let everyone else tell you DNMC; here''s what I like about the picture. I like the sets of lines and how each is different: foreground bushes, red tree line, hazy horizon, even those top clouds. The colors aren''t oversaturated the way so many are over in the Free Study challenge. Nicely composed, well-thought out shot.', '2006-11-06 11:35:45.000000', NULL, 1),
(3005833, 420879, 208, '<td valign="top">There''s something weird about how her head is sort of just stuck there in the bottom corner. Maybe it''s how it''s framed by the fence post and barbed wire? I kind of like the soft focus on her, though.</td>', 'There''s something weird about how her head is sort of just stuck there in the bottom corner. Maybe it''s how it''s framed by the fence post and barbed wire? I kind of like the soft focus on her, though.', '2006-11-06 11:38:39.000000', NULL, 1),
(3005878, 420149, 208, '<td valign="top">Yeah, "Orientation" was on the second line on my mainpage, too - I almost missed it. This is an interesting take on "Portrait in [a] Landscape." I think it needs more contrast. The snow seems a little too gray. I''d also like to see a bit more of the "son" on the right.</td>', 'Yeah, "Orientation" was on the second line on my mainpage, too - I almost missed it. This is an interesting take on "Portrait in [a] Landscape." I think it needs more contrast. The snow seems a little too gray. I''d also like to see a bit more of the "son" on the right.', '2006-11-06 11:51:55.000000', NULL, 1),
(3006149, 417659, 50695, '<td valign="top">the edge of the white area has some weird haloing going on. Good composition, though.</td>', 'the edge of the white area has some weird haloing going on. Good composition, though.', '2006-11-06 12:40:58.000000', NULL, 1),
(3006312, 419987, 50695, '<td valign="top">Just look at those beautiful lines of sunlight, the profound mystery of his hidden face, resonating with the mystery of the background. Utter darkness in his shadows, utter darkness in the background and foreground... while the subject lies in the light that exists between the two. It is as if we are looking at his sleep, rather than him. I''ll start this at 9.</td>', 'Just look at those beautiful lines of sunlight, the profound mystery of his hidden face, resonating with the mystery of the background. Utter darkness in his shadows, utter darkness in the background and foreground... while the subject lies in the light that exists between the two. It is as if we are looking at his sleep, rather than him. I''ll start this at 9.', '2006-11-06 13:11:03.000000', NULL, 1),
(3006412, 419266, 50695, '<td valign="top">the selective desat makes her look gray.</td>', 'the selective desat makes her look gray.', '2006-11-06 13:35:24.000000', NULL, 1),
(3006473, 420542, 30049, '<td valign="top">I like the tone and feel of this overall.  Jury''s still out on the centered composition and the angle of his face.   It''s unique as a portrait from most of the others in the challenge.  On this monitor (not a good one) I''m losing some detail in the black of his shirt and pants.  Sorry about riding the fence on this one...it''s "ok", not loving it, nor really disliking it.  :D  Good luck in the challenge.</td>', 'I like the tone and feel of this overall.  Jury''s still out on the centered composition and the angle of his face.   It''s unique as a portrait from most of the others in the challenge.  On this monitor (not a good one) I''m losing some detail in the black of his shirt and pants.  Sorry about riding the fence on this one...it''s "ok", not loving it, nor really disliking it.  :D  Good luck in the challenge.', '2006-11-06 13:56:38.000000', NULL, 1),
(3006476, 420035, 30049, '<td valign="top">Mike is cool.  Great detail and character coming out in his portrait.  I wish the bg was a little less discernable.  Good luck in the challenge.</td>', 'Mike is cool.  Great detail and character coming out in his portrait.  I wish the bg was a little less discernable.  Good luck in the challenge.', '2006-11-06 13:57:58.000000', NULL, 1),
(3006480, 421098, 30049, '<td valign="top">What a cutie!  Great job on getting superb focus and clarity on her eyes - WOW.  Need to put this one in a frame.  :D  Good luck in the challenge.</td>', 'What a cutie!  Great job on getting superb focus and clarity on her eyes - WOW.  Need to put this one in a frame.  :D  Good luck in the challenge.', '2006-11-06 13:59:12.000000', NULL, 1),
(3006488, 421041, 30049, '<td valign="top">She really stands out with that dark background.  Her face almost seems to have a grungy look to it.  I know she has makeup on, but even her forehead and ears look grunged (is that a word? &lt;grin&gt;).  It''s not a bad thing, in this case I think it works just fine.  The foreground flowers add a nice touch, yet defocused enough to stay out of the visual way.  Best of luck to you in the challenge.</td>', 'She really stands out with that dark background.  Her face almost seems to have a grungy look to it.  I know she has makeup on, but even her forehead and ears look grunged (is that a word? <grin>).  It''s not a bad thing, in this case I think it works just fine.  The foreground flowers add a nice touch, yet defocused enough to stay out of the visual way.  Best of luck to you in the challenge.', '2006-11-06 14:02:35.000000', NULL, 1),
(3006493, 421141, 50695, '<td valign="top">He looks like he''s wearing a stovepipe hat. Nice composition, though. It just looks a little dark on my monitor. No details in the dark areas, including the horse. 6</td>', 'He looks like he''s wearing a stovepipe hat. Nice composition, though. It just looks a little dark on my monitor. No details in the dark areas, including the horse. 6', '2006-11-06 14:05:13.000000', NULL, 1),
(3006515, 420540, 50695, '<td valign="top">a wonderful tableau! it has the fun sort of decadence of the Addams Family combined with the Surreal touch of Man Ray. It''s like a subtler version of Dali. 10</td>', 'a wonderful tableau! it has the fun sort of decadence of the Addams Family combined with the Surreal touch of Man Ray. It''s like a subtler version of Dali. 10', '2006-11-06 14:11:01.000000', NULL, 1),
(3006572, 420932, 50695, '<td valign="top">this strikes me as a fashion shot, not a portrait.</td>', 'this strikes me as a fashion shot, not a portrait.', '2006-11-06 14:25:26.000000', NULL, 1),
(3006580, 420139, 50695, '<td valign="top">this is a cool, fun picture, but I don''t consider it a portrait. Clearly, your model is just another prop putting across your concept. still, I''ll give you a 6.</td>', 'this is a cool, fun picture, but I don''t consider it a portrait. Clearly, your model is just another prop putting across your concept. still, I''ll give you a 6.', '2006-11-06 14:28:08.000000', NULL, 1),
(3006590, 419953, 50695, '<td valign="top">why do homeless people require Joey-Lawrence processing?</td>', 'why do homeless people require Joey-Lawrence processing?', '2006-11-06 14:31:54.000000', NULL, 1),
(3006605, 418191, 50695, '<td valign="top">It disturbs me that he is looking into the distance. She is so clearly in the moment, but he seems to be losing the moment. It''s too bad, because everything else is adding up to an incredibly romantic picture. 6</td>', 'It disturbs me that he is looking into the distance. She is so clearly in the moment, but he seems to be losing the moment. It''s too bad, because everything else is adding up to an incredibly romantic picture. 6', '2006-11-06 14:37:35.000000', NULL, 1),
(3006613, 418796, 50695, '<td valign="top">the selective desat looks corny, as it usually does.</td>', 'the selective desat looks corny, as it usually does.', '2006-11-06 14:40:04.000000', NULL, 1),
