(3014953, 419889, 52549, '<td valign="top">A really excellent shot Judi. Congratulations on your top 10 finish.</td>', 'A really excellent shot Judi. Congratulations on your top 10 finish.', '2006-11-08 15:01:28.000000', NULL, 0),
(3014991, 418201, 42495, '<td valign="top">I suspect voters didn''t score high here because many may assume that a portrait has to be of a person.  Also, warm and cuddly may work better than the scowl.  As far as the picture itself, the thing that jumps out at me is that the eyes seem to be just a tad bit off-center.  It may be an illusion, but it appears as if you were trying to get them centered and missed the mark.  I like the PP but it appears that a bit of color is in the fur instead of B&amp;W, assuming that B&amp;W was your intention for fur.  I would have scored it 6.</td>', 'I suspect voters didn''t score high here because many may assume that a portrait has to be of a person.  Also, warm and cuddly may work better than the scowl.  As far as the picture itself, the thing that jumps out at me is that the eyes seem to be just a tad bit off-center.  It may be an illusion, but it appears as if you were trying to get them centered and missed the mark.  I like the PP but it appears that a bit of color is in the fur instead of B&W, assuming that B&W was your intention for fur.  I would have scored it 6.', '2006-11-08 15:15:20.000000', NULL, 0),
(3015175, 421056, 24454, '<td valign="top">I am so in awe that a guy with no inspiration could turn out a masterpiece work of art like this!  This is one of those photos that will be precious even when your daughter is grown with kids of her own.  The ribon:  just icing on the cake!  Congratulations!<br/><br/><i>Message edited by author 2006-11-08 15:52:56.</i></td>', 'I am so in awe that a guy with no inspiration could turn out a masterpiece work of art like this!  This is one of those photos that will be precious even when your daughter is grown with kids of her own.  The ribon:  just icing on the cake!  Congratulations!', '2006-11-08 15:52:08.000000', '2006-11-08 15:52:56.000000', 0),
(3015182, 421056, 36606, '<td valign="top">wonderful photo! glad u ribboned.</td>', 'wonderful photo! glad u ribboned.', '2006-11-08 15:56:19.000000', NULL, 0),
